-- evt:registry
RegisterEvent(55, "Registry door", function(continueStep)
    if continueStep == 2 then
        evt.SetDoorState(18, DoorAction.Open)
        XeenQuests.hook("m28.registry_lock")
        return
    end
    if continueStep ~= nil then
        evt.StatusText("Incorrect!")
        return
    end
    if not (not (IsQBitSet(QBit(111562)))) then
        evt.StatusText("The registry door stands open.")
        return
    end
    evt.SetMessage("A bronze door with a lock of numbered keys. Above it, in raised letters: STARFLEET REGISTRY NUMBER NCC.")
    evt.AskQuestion(55, 1, 0, 2, "Registry?", {"1701", "NCC-1701", "NCC1701", "NCC 1701"})
end, "Registry door")

