    evt.SimpleMessage("3 - Then subtract another forty-two\nThis final number can get you through")
end, "Statue")

-- evt:verse_3_step
RegisterEvent(89, nil, function()
    evt.StatusText("3 - Then subtract another forty-two This final number can get you through", 6)
end, nil)

-- evt:verse_4
RegisterEvent(90, "Statue", function()
    evt.SimpleMessage("4 - Type in the passcode you now should know\nTo quickly get from this level below")
end, "Statue")

-- evt:verse_4_step
RegisterEvent(91, nil, function()
    evt.StatusText("4 - Type in the passcode you now should know To quickly get from this level below", 6)
end, nil)

-- evt:welcome
RegisterEvent(92, "Statue", function()
    XeenQuests.hook("m28.welcome_statue")
end, "Statue")

-- evt:welcome_first
RegisterEvent(93, nil, function()
    if IsAtLeast(MapVar(6), 1) then
        return
    end
    if not (not (IsQBitSet(QBit(117560)))) then
        return
    end
    SetValue(MapVar(6), 1)
    SetQBit(QBit(117560))
    XeenQuests.hook("m28.welcome_statue")
end, nil)

-- evt:studio_peaceful_groups
RegisterEvent(94, nil, function()
    if evt.GetMapVar("studio_peaceful_groups", 0) ~= 0 then
        return
    end
    evt.SetMapVar("studio_peaceful_groups", 1)
    evt.SetMonGroupBit(50, MonsterBits.Hostile, 0)
end, nil)
